def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Count behaviors.
    opp_d = 0
    for x in opp:
        if x == 'D':
            opp_d += 1
    opp_c = n - opp_d

    # Perfect cooperator: keep cooperation, exploit only at very end.
    if opp_d == 0:
        if n >= 99:
            return 'D'
        return 'C'

    # Perfect/hard defector: defect, rare probe.
    if opp_c == 0:
        if n >= 5 and rng.random() < 0.05:
            return 'C'
        return 'D'

    # Recent windows.
    w = 8 if n >= 8 else n
    recent_opp_d = 0
    recent_my_d = 0
    for i in range(n - w, n):
        if opp[i] == 'D':
            recent_opp_d += 1
        if me[i] == 'D':
            recent_my_d += 1
    recent_opp_c = w - recent_opp_d

    last_me = me[-1]
    last_opp = opp[-1]

    # Detect mutual defection spiral: try to break it.
    if n >= 2 and last_me == 'D' and last_opp == 'D':
        run = 0
        i = n - 1
        while i >= 0 and opp[i] == 'D' and me[i] == 'D':
            run += 1
            i -= 1
        if run >= 2:
            if rng.random() < 0.55:
                return 'C'

    # Endgame: last round always defect (opponent likely does too; DC=5 is best).
    if n >= 99:
        return 'D'
    # Near end, take advantage of likely cooperators.
    if n >= 96:
        if recent_opp_c >= w * 0.75:
            return 'D'
        if last_opp == 'D':
            return 'D'
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    # Heavy recent defection: retaliate firmly.
    if recent_opp_d >= (w * 3) // 4:
        if recent_opp_d >= w - 1:
            return 'D'
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Opponent mostly cooperative recently: stay cooperative, occasional test.
    if recent_opp_d <= 1:
        # If we defected last round and they cooperated, be careful: they're forgiving.
        if last_me == 'D' and last_opp == 'C':
            # Don't overexploit a nice opponent too early; small chance to continue.
            if n < 60 and rng.random() < 0.25:
                return 'D'
            return 'C'
        # Rare probe against heavy cooperators to gain 5 while preserving trust.
        if opp_d * 6 <= n and n >= 12:
            if n % 11 == 0:
                return 'D'
        return 'C'

    # Moderate defection: tit-for-tat with limited forgiveness.
    if last_opp == 'D':
        # If opponent just defected but overall mostly cooperative, forgive sometimes.
        if opp_d * 4 <= n and recent_opp_d <= 2:
            if rng.random() < 0.25:
                return 'C'
        return 'D'

    # Opponent cooperated last round; reward unless they are exploiting us.
    if opp_d * 3 > n:
        # Opponent is aggressive overall: be cautious.
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    return 'C'
